CREATE TABLE schema_version_v4(version INTEGER PRIMARY KEY CHECK(version IN(1,2,3,4)),backend TEXT NOT NULL CHECK(backend='sqlite'),checksum TEXT NOT NULL) STRICT;
INSERT INTO schema_version_v4 SELECT * FROM schema_version;
DROP TABLE schema_version;
ALTER TABLE schema_version_v4 RENAME TO schema_version;
CREATE TABLE audit_event_v4(id TEXT PRIMARY KEY,org_id TEXT REFERENCES organization(id),subject_id TEXT,employee_id TEXT,operation TEXT NOT NULL CHECK(operation IN('OP-ORG-05','OP-ORG-06','OP-ORG-08','OP-SEC-01','OP-SEC-02','OP-SEC-03','OP-SEC-06','AUTH-LOGIN','AUTH-STEP-UP','AUTH-LOGOUT','AUTH-BIND','AUTH-UNBIND')),purpose TEXT NOT NULL CHECK(purpose IN('organization_management','security_administration','')),request_id TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('allowed','denied')),recorded_at INTEGER NOT NULL,grant_id TEXT,actor_kind TEXT NOT NULL DEFAULT 'application' CHECK(actor_kind IN('application','local_maintenance','legacy_unattributed')),actor_uid INTEGER,actor_host_hash BLOB CHECK(actor_host_hash IS NULL OR length(actor_host_hash)=32),target_subject_id TEXT,identity_digest BLOB CHECK(identity_digest IS NULL OR length(identity_digest)=32),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,grant_id) REFERENCES access_grant(org_id,id),FOREIGN KEY(org_id,target_subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(identity_digest,org_id,target_subject_id) REFERENCES subject_identity(digest,org_id,subject_id),CHECK(subject_id IS NULL OR org_id IS NOT NULL),CHECK(employee_id IS NULL OR org_id IS NOT NULL),CHECK(grant_id IS NULL OR org_id IS NOT NULL),CHECK(target_subject_id IS NULL OR org_id IS NOT NULL),CHECK(outcome<>'denied' OR employee_id IS NULL),CHECK(outcome<>'denied' OR grant_id IS NULL),CHECK((actor_kind='application' AND operation NOT IN('AUTH-BIND','AUTH-UNBIND') AND actor_uid IS NULL AND actor_host_hash IS NULL AND target_subject_id IS NULL AND identity_digest IS NULL) OR (actor_kind='local_maintenance' AND operation IN('AUTH-BIND','AUTH-UNBIND') AND outcome='allowed' AND purpose='security_administration' AND org_id IS NOT NULL AND subject_id IS NULL AND employee_id IS NULL AND grant_id IS NULL AND actor_uid IS NOT NULL AND actor_uid BETWEEN 0 AND 4294967295 AND actor_host_hash IS NOT NULL AND target_subject_id IS NOT NULL AND identity_digest IS NOT NULL) OR (actor_kind='legacy_unattributed' AND operation IN('AUTH-BIND','AUTH-UNBIND') AND actor_uid IS NULL AND actor_host_hash IS NULL AND identity_digest IS NULL AND ((target_subject_id IS NULL AND subject_id IS NULL) OR (target_subject_id IS NOT NULL AND subject_id IS NOT NULL AND target_subject_id=subject_id))))) STRICT;
INSERT INTO audit_event_v4 SELECT id,org_id,subject_id,employee_id,operation,purpose,request_id,outcome,recorded_at,grant_id,CASE WHEN operation IN('AUTH-BIND','AUTH-UNBIND') THEN 'legacy_unattributed' ELSE 'application' END,NULL,NULL,CASE WHEN operation IN('AUTH-BIND','AUTH-UNBIND') THEN subject_id ELSE NULL END,NULL FROM audit_event;
DROP TABLE audit_event;
ALTER TABLE audit_event_v4 RENAME TO audit_event;
CREATE INDEX audit_subject ON audit_event(org_id,subject_id);
CREATE INDEX audit_employee ON audit_event(org_id,employee_id);
CREATE INDEX audit_grant ON audit_event(org_id,grant_id);
